class Solution {
public:
    string smallestSubsequence(string s) {
        vector<int> last(26, 0);
        int n = s.size();
        for (int i = 0; i < n; ++i) last[s[i] - 'a'] = i;

        string stack = "";
        vector<bool> seen(26, false);

        for (int i = 0; i < n; ++i) {
            char c = s[i];
            if (!seen[c - 'a']) {
                while (!stack.empty() && stack.back() > c && last[stack.back() - 'a'] > i) {
                    seen[stack.back() - 'a'] = false;
                    stack.pop_back();
                }
                stack.push_back(c);
                seen[c - 'a'] = true;
            }
        }
        return stack;
    }
};

class Solution {
    public String smallestSubsequence(String s) {
        int[] last = new int[26];
        for (int i = 0; i < s.length(); ++i) last[s.charAt(i) - 'a'] = i;

        StringBuilder sb = new StringBuilder();
        boolean[] seen = new boolean[26];

        for (int i = 0; i < s.length(); ++i) {
            char c = s.charAt(i);
            if (!seen[c - 'a']) {
                while (sb.length() > 0 && sb.charAt(sb.length() - 1) > c &&
                       last[sb.charAt(sb.length() - 1) - 'a'] > i) {
                    seen[sb.charAt(sb.length() - 1) - 'a'] = false;
                    sb.deleteCharAt(sb.length() - 1);
                }
                sb.append(c);
                seen[c - 'a'] = true;
            }
        }
        return sb.toString();
    }
}

var smallestSubsequence = function(s) {
    const last = new Map();
    for (let i = 0; i < s.length; i++) last.set(s[i], i);

    const stack = [];
    const seen = new Set();

    for (let i = 0; i < s.length; i++) {
        const c = s[i];
        if (!seen.has(c)) {
            while (stack.length > 0 && stack[stack.length - 1] > c && last.get(stack[stack.length - 1]) > i) {
                seen.delete(stack.pop());
            }
            stack.push(c);
            seen.add(c);
        }
    }
    return stack.join('');
};
